"""Final all-workstream report including donor-tail chemistry and secondary scores."""
from pathlib import Path
import sys,json,importlib.util
import numpy as np,pandas as pd
from scipy.spatial.distance import cdist
ROOT=Path(__file__).resolve().parents[1];CHILD=ROOT/'chemical_tail_sensitivity'
def main():
 # Independent global steric replay for the accepted relaxedG76 model.
 spec=importlib.util.spec_from_file_location('nativeprep',ROOT/'scripts/01_prepare_and_validate_native.py');prep=importlib.util.module_from_spec(spec);spec.loader.exec_module(prep);from Bio.PDB import MMCIFParser
 parser=MMCIFParser(QUIET=True,auth_chains=False);s=parser.get_structure('r',str(prep.PRIOR/'references/8RX0.cif'))[0];z=np.load(ROOT/'references/8RX0_locally_relaxed_G76.npz');points=np.vstack([z['G75_O'],z['G76_xyz']]);atoms=[]
 for ch in ['F','I']:
  for r in s[ch]:
   if r.id[0]!=' ':continue
   for a in r:
    if a.element not in ['H','D'] and not(ch=='I' and r.id[1]==75 and a.name=='O'):atoms.append((ch,r.id[1],a.name,a.element,a.coord))
 atoms.append(('F',93,'SG','S',z['E2_SG']));excluded={(0,'I',75,'C'),(0,'I',75,'CA'),(1,'I',75,'C'),(1,'I',75,'CA'),(2,'I',75,'C'),(3,'F',93,'SG'),(3,'F',93,'CB'),(2,'F',93,'SG'),(4,'F',93,'SG')};mask=np.array([[(i,ch,r,n) not in excluded for ch,r,n,_,_ in atoms] for i in range(5)]);nr=np.array([1.52,1.55,1.7,1.7,1.52]);rr=np.array([prep.e.RAD[el] for _,_,_,el,_ in atoms]);over=nr[:,None]+rr[None,:]-cdist(points,np.array([a[4] for a in atoms]));ov=float(over[mask].max());assert ov<=.8,'Global tail clash replay failed';assert abs(np.linalg.norm(z['G76_xyz'][2]-z['E2_SG'])-1.8)<.04
 # Update core report from current verified artifacts,not stale drafts.
 spec=importlib.util.spec_from_file_location('mainreport',ROOT/'scripts/08_write_complete_report.py');report=importlib.util.module_from_spec(spec);spec.loader.exec_module(report);report.main();status=json.loads((ROOT/'validation/scientific_status.json').read_text());tail=json.loads((ROOT/'validation/locally_relaxed_tail_models.json').read_text());checks={m['reference']:m['record'] for m in tail['models']};assert checks['8RX0']['validated_geometry_only'];secondary=pd.read_csv(CHILD/'results/native_metrics.tsv',sep='\t');m=secondary[(secondary.reference=='8RX0_relaxed_G76')&(secondary.anchor=='VHL')&(secondary.score=='productive_fraction')].iloc[0];ver=json.loads((CHILD/'validation/independent_verification.json').read_text());assert ver['status']=='PASS';status.update({'chemical_tail_native8RX0_geometry':'PASS','chemical_tail_native8R5H_geometry':'FAIL','G75O_relaxation_A':checks['8RX0']['G75O_displacement_A'],'independent_global_tail_core_overlap_A':ov,'secondary_chemical_tail_AUROC':float(m.AUROC),'secondary_chemical_tail_exact_p':float(m.exact_two_sided_AUROC_p),'full_physiological_endpoint_validated':False,'new_GNN_training_run':False});(ROOT/'validation/scientific_status.json').write_text(json.dumps(status,indent=2)+'\n')
 text=(ROOT/'FINDINGS.md').read_text();text+='''\n## Additional chemical-tail reconstruction: saved after the primary comparison\n\nA chemically explicit missingGly76 tail was reconstructed using only the ubiquitinGly75 backbone andE2Cys93 sulfur placement. No substrate lysine or degradation label enters these fits. Early fixed-atom trials were retained:they could satisfy some bonds while violating neighboring peptide planarity or creating clashes,so they were not released. The peptide carbonyl planes,trans-amide geometry,declared ideal bond lengths/angles and bonded1–2/1–3 exclusions were checked explicitly.\n\nThe final bounded attempt permitted only the observedGly75 carbonyl oxygen plus missingGly76 atoms to move,with all other protein backbone atoms fixed. It achieved the declared geometry/clash gates for8RX0 after movingGly75O by0.944Å. Independent dense-distance replay over all deposited E2/Ub atoms confirms maximum checked nonbonded overlap below0.8Å and C–S distance1.800Å. Cys93SG remains transferred/modelled because it is absent from8RX0;unresolved sidechains remain absent. This is a geometrically consistent local model,not a physiological reaction simulation or an energy-minimized complete catalytic complex. The corresponding8R5H constrained reconstruction failed the unchanged gates and is not promoted.\n\nThe new8RX0 modeled endpoint places native-backbone K456 at approximately18.7Å,close to the paper's18.4Å illustration. This is an independent geometric consistency check,not exact reproduction and not a distance fitted to K456.\n\nThe corrected endpoint was then assessed on all141 poses/28,341 frames as a separately frozen secondary sensitivity,not a replacement for the initial8R5H primary. Both raw-frame geometry and AUROC arithmetic have an independent replay.\n\n'''
 text+=f'Secondary productive-fraction AUROC={m.AUROC:.3f},exact target permutation p={m.exact_two_sided_AUROC_p:.6f}. The original primary remains0.500. Neither supports a reliable degradation classifier. All alternative thresholds and orientations remain in chemical_tail_sensitivity/results/;no best-case variant is selected as validation.\n\n'
 text+='''The matched GNN inputs still encode the declared primary SY8 surrogate;they were not silently replaced by this secondary endpoint. The full kinome annotation is likewise the declared primary diagnostic. Keeping these separate prevents a succession of physical reference changes from becoming undocumented outcome-driven feature selection.\n\n## Completion and remaining scientific limits\n\nCompleted:native-backbone correspondence correction;three-reference preparation andcontrols;two full eight-target MD comparisons including the locally repaired modeled tail;independent coordinate/metric checks;16 matched GNN input/runtime checks;723-pose kinome diagnostic;all scripts,receipts and findings. No new training or new simulations were performed.\n\nStill unresolved:full physiological catalytic-reference validation,the archived-versus-supplier molecular identity,correct pocket placement throughout the kinome,and independent biological validation with more than two non-degrader targets. These are explicit limitations,not PASS statuses. The saved provisional GNN data do not constitute a trained or validated GNN result.\n'''
 (ROOT/'FINDINGS.md').write_text(text)
 from docx import Document
 doc=Document()
 for line in text.splitlines():
  if line.startswith('# '):doc.add_heading(line[2:],0)
  elif line.startswith('## '):doc.add_heading(line[3:],1)
  elif line:doc.add_paragraph(line)
 doc.save(ROOT/'FINDINGS.docx');(ROOT/'validation/final_tail_replay.json').write_text(json.dumps({'status':'PASS','global_nonbonded_E2Ub_overlap_A':ov,'G76C_E2SG_A':float(np.linalg.norm(z['G76_xyz'][2]-z['E2_SG'])),'source_script_sha256':prep.sha(__file__),'target_or_labels_used_in_tailfit':False,'chemical_sensitivity_independent_verification':'PASS','physiological_reaction_validated':False},indent=2)+'\n');print('Final:primaryAUROC0.500;secondarychemical-tailAUROC',m.AUROC,';no validatedclassifier.')
if __name__=='__main__':main()
